-- 90 VERIFY — [GAP445 2026-10-15] GAP 445 조회 전용 (전체 F5, 값 입력 없음)
-- * 기대: V1 마커 2줄 PASS · V2 VALID / 오류 0 / 의존 INVALID 0 · V3 Current 블록은 Current~MF 분기 사이, MF 블록은 MF~SF 분기 사이 PASS
--         · V4 MKT_FCST_PP 적재 문장 수 = 6 (Current 2 · MF 2 · SF 2) PASS
-- * 화면 확인(README 4단계): MKT FCST[P+P] 를 화면 설정에 둔 사용자로 Current 조회 → 계획구간 값이 MKT_FCST 와 같다.
SET LINESIZE 220 PAGESIZE 500
SET DEFINE OFF
COLUMN CHK FORMAT A10
COLUMN JUDGE FORMAT A60
SELECT 'V1 마커' CHK, COUNT(*) N, LISTAGG(LINE, ',') WITHIN GROUP (ORDER BY LINE) LINES,
       CASE WHEN COUNT(*) = 2 THEN 'PASS' ELSE 'FAIL (미적용 또는 마커 수 불일치)' END JUDGE
  FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%GAP445 2026-10-15%';
SELECT 'V2 상태' CHK, O.OBJECT_TYPE, O.STATUS, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*) FROM USER_ERRORS E WHERE E.NAME=O.OBJECT_NAME AND E.TYPE=O.OBJECT_TYPE) ERR_CNT,
       (SELECT COUNT(*) FROM USER_OBJECTS X WHERE X.STATUS<>'VALID' AND X.OBJECT_NAME IN (SELECT NAME FROM USER_DEPENDENCIES WHERE REFERENCED_NAME='PKG_DMF0082')) DEP_INVALID
  FROM USER_OBJECTS O WHERE O.OBJECT_NAME='PKG_DMF0082' ORDER BY O.OBJECT_TYPE;
SELECT 'V3 위치' CHK, CB.L CUR_BR, MC.L CUR_MARK, MB.L MF_BR, MM.L MF_MARK, SB.L SF_BR,
       CASE WHEN CB.L < MC.L AND MC.L < MB.L AND MB.L < MM.L AND MM.L < SB.L THEN 'PASS' ELSE 'FAIL — 블록 위치 이상' END JUDGE
  FROM (SELECT (SELECT MIN(S.LINE) FROM USER_SOURCE S WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND RTRIM(S.TEXT, CHR(10)||CHR(13)) = '    IF p_version_type LIKE ''%Current%'' OR p_version_type LIKE ''%current%'' THEN'
   AND S.LINE BETWEEN (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND RTRIM(TEXT, CHR(10)||CHR(13)) = 'PROCEDURE P_DMF0082_GET_MAIN_DATA')
                  AND (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE 'PROCEDURE P_DMF0082_GET_MAIN_DATA_CURRENT%')) L FROM DUAL) CB,
       (SELECT (SELECT MIN(S.LINE) FROM USER_SOURCE S WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND RTRIM(S.TEXT, CHR(10)||CHR(13)) = '    IF p_version_type LIKE ''%MF%'' THEN'
   AND S.LINE BETWEEN (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND RTRIM(TEXT, CHR(10)||CHR(13)) = 'PROCEDURE P_DMF0082_GET_MAIN_DATA')
                  AND (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE 'PROCEDURE P_DMF0082_GET_MAIN_DATA_CURRENT%')) L FROM DUAL) MB,
       (SELECT (SELECT MIN(S.LINE) FROM USER_SOURCE S WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND RTRIM(S.TEXT, CHR(10)||CHR(13)) = '    IF p_version_type LIKE ''%SF%'' THEN'
   AND S.LINE BETWEEN (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND RTRIM(TEXT, CHR(10)||CHR(13)) = 'PROCEDURE P_DMF0082_GET_MAIN_DATA')
                  AND (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE 'PROCEDURE P_DMF0082_GET_MAIN_DATA_CURRENT%')) L FROM DUAL) SB,
       (SELECT MIN(LINE) L FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '        /* [GAP445 2026-10-15] MKT_FCST [P+P] Current%') MC,
       (SELECT MIN(LINE) L FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '        /* [GAP445 2026-10-15] MKT_FCST [P+P] MF%') MM;
SELECT 'V4 문장' CHK, COUNT(*) N, CASE WHEN COUNT(*) = 6 THEN 'PASS' ELSE 'FAIL — 회신' END JUDGE
  FROM USER_SOURCE S WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND S.TEXT LIKE '%''MKT_FCST_PP'' AS MEASURE%'
   AND S.LINE BETWEEN (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND RTRIM(TEXT, CHR(10)||CHR(13)) = 'PROCEDURE P_DMF0082_GET_MAIN_DATA')
                  AND (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE 'PROCEDURE P_DMF0082_GET_MAIN_DATA_CURRENT%');
